import type { AlbumConfig } from "../types";

export interface CloudWord {
  /** The word as it will be shown. */
  text: string;
  /** How many greetings-worth of occurrences it had. */
  count: number;
  /** How large to draw it, from 0 (as rare as anything shown) to 1. */
  weight: number;
}

export interface WordCloudOptions {
  /** How many words the cloud may show at most. */
  limit?: number;
  /** Words shorter than this are dropped before counting. */
  minLength?: number;
}

/**
 * Hebrew's most common function words, which would otherwise dominate any
 * count and say nothing about the occasion.
 *
 * Hebrew glues its prepositions and articles onto the front of a word, so the
 * same stem appears as ל-, ב-, כ-, מ-, ש- and ו- variants. Stripping those
 * prefixes properly needs a morphological analyser; a cloud does not warrant
 * one, so the common standalone forms are listed and the prefixed variants of
 * real words are simply counted as the separate words they appear to be.
 */
const HEBREW_STOP_WORDS = new Set([
  "של", "את", "על", "עם", "אל", "מן", "כמו", "אשר", "זה", "זאת", "זו",
  "הוא", "היא", "הם", "הן", "אני", "אתה", "אתם", "אנחנו", "אנו",
  "לי", "לך", "לו", "לה", "לנו", "לכם", "להם", "אותי", "אותך", "אותו",
  "יש", "אין", "היה", "היתה", "הייתה", "היו", "להיות", "יהיה",
  "כל", "כלל", "גם", "רק", "עוד", "כבר", "מאוד", "יותר", "הכי", "פחות",
  "אבל", "אם", "כי", "אז", "לא", "כן", "מה", "מי", "איך", "כאשר", "כדי",
  "אחרי", "לפני", "בין", "תוך", "בלי", "אצל", "עד", "מתוך", "בגלל",
  "שלי", "שלך", "שלו", "שלה", "שלנו", "שלכם", "שלהם", "כמה", "איזה",
  "היום", "אתכם", "אותנו", "להם", "עלי", "עליך", "אליך", "ואת", "וגם",
]);

const ENGLISH_STOP_WORDS = new Set([
  "the", "and", "for", "you", "your", "with", "that", "this", "was", "are",
  "have", "has", "from", "our", "all", "but", "not", "will", "can", "his",
  "her", "they", "them", "who", "what", "when", "how", "been", "were", "very",
]);

/**
 * Counts the words across an album's greetings, heaviest first.
 *
 * The result is deterministic — ties break alphabetically — because the cloud
 * is rendered on the server as well as the client, and on paper. A cloud that
 * shuffled between renders would trip hydration and print differently from
 * what the owner previewed.
 */
export function buildWordCloud(
  album: AlbumConfig,
  { limit = 45, minLength = 3 }: WordCloudOptions = {},
): CloudWord[] {
  const counts = new Map<string, number>();

  for (const page of album.pages) {
    for (const word of wordsIn(page.html)) {
      if (word.length < minLength) continue;
      if (HEBREW_STOP_WORDS.has(word) || ENGLISH_STOP_WORDS.has(word)) continue;
      counts.set(word, (counts.get(word) ?? 0) + 1);
    }
  }

  const ranked = [...counts.entries()]
    .sort(([aWord, aCount], [bWord, bCount]) =>
      bCount - aCount || aWord.localeCompare(bWord, "he"),
    )
    .slice(0, limit);

  if (ranked.length === 0) return [];

  // Weight follows how much more common a word actually is, rather than
  // stretching whatever spread exists across the full size range: in a young
  // album where the winner appears twice and everything else once, stretching
  // would print two words huge and the rest as fine print. Counting is
  // logarithmic and tops out at four times the rarest word, past which more
  // type says nothing further and only crowds the page.
  const rarest = ranked[ranked.length - 1][1];
  const floor = Math.log1p(rarest);
  const ceiling = Math.log1p(rarest * 4) - floor;

  return (
    ranked
      .map(([text, count]) => ({
        text,
        count,
        weight: Math.min(1, (Math.log1p(count) - floor) / ceiling),
      }))
      // Left in frequency order the cloud reads as a headline above a
      // paragraph. Dealing the words out by a hash of themselves scatters the
      // large ones through the small — and because the hash is of the word, the
      // server, the browser and the printed sheet all deal the same hand.
      .sort((a, b) => hash(a.text) - hash(b.text))
  );
}

function hash(word: string): number {
  let value = 0x811c9dc5;
  for (let i = 0; i < word.length; i += 1) {
    value = Math.imul(value ^ word.charCodeAt(i), 0x01000193);
  }
  return value >>> 0;
}

/** Plain words out of greeting markup, stripped of tags, entities and niqqud. */
function wordsIn(html: string): string[] {
  const text = html
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;|&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    // Niqqud and cantillation are invisible to a reader scanning a cloud but
    // would split one word into several counts.
    .replace(/[\u0591-\u05C7]/g, "");

  return (text.match(/[\p{L}\p{M}]+/gu) ?? []).map((word) => word.toLowerCase());
}
